import re
from datetime import datetime


def extract(text: str) -> dict:
    def parse_amount(value: str) -> float:
        cleaned = value.replace(',', '').strip()
        try:
            return float(cleaned)
        except Exception:
            raise ValueError('Invalid amount')

    def parse_date(value: str) -> str:
        s = value.strip()
        for fmt in ('%d/%m/%Y', '%d %b %Y', '%d %B %Y'):
            try:
                return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
            except Exception:
                pass
        raise ValueError('Invalid date')

    amount_match = re.search(
        r'(?im)^\s*(?:Total\s+Amount\s+Due\s+Rs\.?|Amount\s+payable\s+INR)\s*([0-9][0-9,]*\.\d{2})\s*$',
        text,
    )
    if not amount_match:
        raise ValueError('Missing amount label')

    due_match = re.search(
        r'(?im)^\s*(?:Payment\s+Due\s+Date|Pay\s+by)\s+([0-9]{1,2}(?:/[0-9]{1,2}/[0-9]{4}|\s+[A-Za-z]{3,9}\s+[0-9]{4}))\s*$',
        text,
    )
    if not due_match:
        raise ValueError('Missing due date label')

    return {
        'type': 'bill_due',
        'provider': 'HDFC Bank',
        'amount': parse_amount(amount_match.group(1)),
        'currency': 'INR',
        'due_date': parse_date(due_match.group(1)),
    }
